package com.servicerca.service;import lombok.extern.slf4j.Slf4j;import org.springframework.beans.factory.annotation.Value;import org.springframework.mail.javamail.*;import org.springframework.stereotype.Service;import org.springframework.transaction.event.*;@Service @Slf4j public class JobMailService{private final JavaMailSender sender;private final String from;public JobMailService(JavaMailSender s,@Value("${app.mail-from}")String f){sender=s;from=f;}@TransactionalEventListener(phase=TransactionPhase.AFTER_COMMIT)public void accepted(JobAcceptedEvent e){try{var m=sender.createMimeMessage();var h=new MimeMessageHelper(m,true,"UTF-8");h.setFrom(from);h.setTo(e.clientEmail());h.setSubject("Profesional confirmado · ServiCerca");h.setText("<div style='font-family:Arial;max-width:600px;margin:auto;color:#10254b'><div style='background:#075ccc;color:white;padding:24px;border-radius:16px 16px 0 0'><h1>¡Profesional confirmado!</h1></div><div style='padding:24px;border:1px solid #dce5f5'><p>Hola "+safe(e.clientName())+",</p><p><b>"+safe(e.professionalName())+"</b> fue elegido para <b>"+safe(e.title())+"</b>.</p><p>Zona: "+safe(e.locality())+"</p><a style='display:inline-block;background:#075ccc;color:white;padding:12px 20px;border-radius:8px;text-decoration:none' href='#'>Ver trabajo en ServiCerca</a></div></div>",true);sender.send(m);log.info("job_acceptance_email sent requestId={}",e.requestId());}catch(Exception ex){log.warn("job_acceptance_email failed requestId={} reason={}",e.requestId(),ex.getClass().getSimpleName());}}private static String safe(String s){return s==null?"":s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;");}}
